static XPLMDataRef h[T_N];
static int primed;

static const char *weave(int id, char *o, int cap)
{
    const struct twine *t;
    int i, n;

    if (id < 0 || id >= T_N || cap < TW)
        return 0;

    t = &tw[id];
    n = (int)t->n;
    if (n > cap)
        n = cap;

    for (i = 0; i < n; ++i)
    {
        unsigned m = s0 + (unsigned)i * s1 + (unsigned)id * s2;
        o[i] = (char)(t->b[i] ^ (unsigned char)(m & 0xFFu));
    }

    o[n - 1] = 0;
    return o;
}

static XPLMDataRef pick(int id)
{
    char s[TW];

    if (id < 0 || id >= T_N)
        return 0;

    if (!h[id])
    {
        const char *w = weave(id, s, (int)sizeof(s));
        if (w)
            h[id] = XPLMFindDataRef(w);
        memset(s, 0, sizeof(s));
    }

    return h[id];
}

void tel_init(void)
{
    int i;

    if (primed)
        return;

    for (i = 0; i < T_N; ++i)
        (void)pick(i);

    primed = 1;
}

void tel_release(void)
{
    memset(h, 0, sizeof(h));
    primed = 0;
}

float tel_f(int id)
{
    XPLMDataRef r = pick(id);
    return r ? XPLMGetDataf(r) : 0.0f;
}

int tel_i(int id)
{
    XPLMDataRef r = pick(id);
    return r ? XPLMGetDatai(r) : 0;
}

int tel_iv(int id, int *v, int n)
{
    XPLMDataRef r = pick(id);
    return r ? XPLMGetDatavi(r, v, 0, n) : 0;
}

void tel_setf(int id, float v)
{
    XPLMDataRef r = pick(id);
    if (r)
        XPLMSetDataf(r, v);
}

void tel_seti(int id, int v)
{
    XPLMDataRef r = pick(id);
    if (r)
        XPLMSetDatai(r, v);
}
